def main(argv=None):
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--onoff-dependency',action='store_true');p.add_argument('--output-dir',type=Path,default=Path(__file__).resolve().parent/'nba_passing_output');p.add_argument('--data-dir',type=Path);p.add_argument('--draws',type=int,default=500);p.add_argument('--skip-network-plots',action='store_true',help='Refresh summary without redrawing saved network figures');p.add_argument('--download',action='store_true',help='Fetch on/off tables, select previous-season players, and complete passing profiles before analysis');a=p.parse_args(argv);root=a.output_dir;out=a.data_dir or root/'onoff_dependency';
 if a.download:
  from fetch_onoff import main as fetch_onoff
  from select_onoff_stars import main as select_stars
  from fetch_onoff_networks import main as fetch_networks
  fetch_onoff(['--destination',str(out)]);select_stars(['--output-dir',str(root),'--data-dir',str(out)]);fetch_networks(['--output-dir',str(root),'--data-dir',str(out)])
 selected=pd.read_csv(out/'selected_stars.csv');players=pd.read_csv(root/'2025-26/team_season_topics/player_games.csv',dtype={'GAME_ID':str});games=pd.read_csv(root/'2025-26/team_season_topics/team_games.csv',dtype={'GAME_ID':str});games['date']=pd.to_datetime(games.GAME_DATE);advanced=pd.read_csv(root/'star_dependency_study/game_cache/2025-26_team_advanced.csv.gz',dtype={'GAME_ID':str});games.GAME_ID=games.GAME_ID.str.zfill(10);players.GAME_ID=players.GAME_ID.str.zfill(10);advanced.GAME_ID=advanced.GAME_ID.str.zfill(10);games=games.merge(advanced[['TEAM_ID','GAME_ID','POSS']],on=['TEAM_ID','GAME_ID'],validate='one_to_one');rng=np.random.default_rng(20261117);rows=[];draws=[];game_rows=[];manifest=[]
 for z in selected.itertuples():
  folder=out/'networks'/z.team;audit=json.loads((folder/'audit.json').read_text());assert audit['complete'],z.team;pf=folder/'present_passing_matrix.csv';af=folder/'absent_passing_matrix.csv';F=pd.read_csv(pf,index_col=0);Aframe=pd.read_csv(af,index_col=0);assert F.index.astype(int).tolist()==Aframe.index.astype(int).tolist() and F.columns.tolist()==Aframe.columns.tolist();P=F.to_numpy(float);A=Aframe.to_numpy(float);T=P+A;ids=F.index.astype(int).tolist();hi=ids.index(z.star_id);assert P.min()>=0 and A.min()>=0 and not np.diag(T).any() and A[hi].sum()+A[:,hi].sum()==0;assert A.sum()>0 and P.sum()>0
  for f in [pf,af,folder/'audit.json']:manifest.append(dict(team=z.team,path=str(f),sha256=hashlib.sha256(f.read_bytes()).hexdigest()))
